(658,610,$mw$F42CF75397BD6460E8D876298A1609C6285C907665AF8A27883D0B5FDC69157A$mw$,$mw$e6c44cd73bb6f3f852ac903ff9d926d3$mw$,$mw$$mw$,$mw${"Id":610,"StageId":1,"CategoryId":1,"Points":10,"TitleAr":"إيجاد الحد الناقص في الجمع","TitleEn":"Find a missing addend","QuestionTextAr":"أي عدد نضيفه إلى 486 لنحصل على 725؟","QuestionTextEn":"What must be added to 486 to obtain 725?","DetailedSolutionAr":"المبدأ: لإيجاد حد مجهول في الجمع نطرح الحد المعلوم من الناتج. إذا كان 486 + س = 725، فـ س = 725 − 486 = 239. التحقق: 486 + 239 = 725.","DetailedSolutionEn":"Rule: To find a missing addend, subtract the known addend from the total. From 486 + x = 725, compute x = 725 − 486 = 239. Check: 486 + 239 = 725.","YoutubeSolutionUrl":null,"EditorialDetailsJson":null,"Options":[{"Id":2429,"Order":1,"LatexCode":"229","IsCorrect":false},{"Id":2430,"Order":2,"LatexCode":"249","IsCorrect":false},{"Id":2431,"Order":3,"LatexCode":"239","IsCorrect":true},{"Id":2432,"Order":4,"LatexCode":"339","IsCorrect":false}]}$mw$::jsonb,$mw${"Hints":[{"Ar":"الطرح يعكس الجمع.","En":"Subtraction reverses addition."},{"Ar":"اطرح الحد المعروف من المجموع المطلوب.","En":"Subtract the known addend from the required total."}],"Title":{"Ar":"إيجاد الحد الناقص في الجمع","En":"Find a missing addend"},"Points":10,"Options":[{"Reason":{"Ar":"486+229=715، أي أقل بعشرة.","En":"486+229=715, ten too low."},"ErrorType":"incorrect-option","IsCorrect":false,"LatexCode":"229"},{"Reason":{"Ar":"486+249=735، أي أكثر بعشرة.","En":"486+249=735, ten too high."},"ErrorType":"incorrect-option","IsCorrect":false,"LatexCode":"249"},{"Reason":null,"ErrorType":"","IsCorrect":true,"LatexCode":"239"},{"Reason":{"Ar":"486+339=825، أي أكثر بمئة.","En":"486+339=825, a hundred too high."},"ErrorType":"incorrect-option","IsCorrect":false,"LatexCode":"339"}],"StageId":1,"Question":{"Ar":"أي عدد نضيفه إلى 486 لنحصل على 725؟","En":"What must be added to 486 to obtain 725?"},"Solution":{"Idea":{"Ar":"نجد الحد المفقود بطرح الحد المعروف من المجموع.","En":"Find the missing addend by subtracting the known addend from the total."},"Unit":{"Ar":"بلا وحدة قياس","En":"Dimensionless"},"Steps":[{"Ar":"نبحث عن الفرق بين المجموع المطلوب 725 والعدد المعروف 486.","En":"Find the difference between the required total 725 and the known number 486."},{"Ar":"من 486 إلى 500 نضيف 14، ومن 500 إلى 725 نضيف 225.","En":"Add 14 to reach 500 from 486, then 225 to reach 725."},{"Ar":"المجموع المضاف 14+225=239.","En":"The total added is 14+225=239."}],"Result":{"Ar":"$239$","En":"$239$"},"CommonError":{"Ar":"انتبه للحمل ولجميع الحدود المعطاة.","En":"Account for carrying and every given term."},"FormulaLatex":"725-486","Substitution":{"Ar":"$725-486=239$","En":"$725-486=239$"},"Verification":{"Ar":"$486+239=725$","En":"$486+239=725$"}},"TrackIds":[2],"CategoryId":1,"PrimarySkillId":1,"DifficultyLevel":1,"SecondarySkillIds":[]}$mw$::jsonb,$mw${"DifficultyLevel":1,"Hints":[{"Ar":"الطرح يعكس الجمع.","En":"Subtraction reverses addition."},{"Ar":"اطرح الحد المعروف من المجموع المطلوب.","En":"Subtract the known addend from the required total."}],"Solution":{"Idea":{"Ar":"نجد الحد المفقود بطرح الحد المعروف من المجموع.","En":"Find the missing addend by subtracting the known addend from the total."},"Unit":{"Ar":"بلا وحدة قياس","En":"Dimensionless"},"Steps":[{"Ar":"نبحث عن الفرق بين المجموع المطلوب 725 والعدد المعروف 486.","En":"Find the difference between the required total 725 and the known number 486."},{"Ar":"من 486 إلى 500 نضيف 14، ومن 500 إلى 725 نضيف 225.","En":"Add 14 to reach 500 from 486, then 225 to reach 725."},{"Ar":"المجموع المضاف 14+225=239.","En":"The total added is 14+225=239."}],"Result":{"Ar":"$239$","En":"$239$"},"CommonError":{"Ar":"انتبه للحمل ولجميع الحدود المعطاة.","En":"Account for carrying and every given term."},"FormulaLatex":"725-486","Substitution":{"Ar":"$725-486=239$","En":"$725-486=239$"},"Verification":{"Ar":"$486+239=725$","En":"$486+239=725$"}},"Distractors":[{"ErrorType":"incorrect-option","Reason":{"Ar":"486+229=715، أي أقل بعشرة.","En":"486+229=715, ten too low."},"Order":1},{"ErrorType":"incorrect-option","Reason":{"Ar":"486+249=735، أي أكثر بعشرة.","En":"486+249=735, ten too high."},"Order":2},{"ErrorType":"","Reason":null,"Order":3},{"ErrorType":"incorrect-option","Reason":{"Ar":"486+339=825، أي أكثر بمئة.","En":"486+339=825, a hundred too high."},"Order":4}]}$mw$,$mw$نجد الحد المفقود بطرح الحد المعروف من المجموع.

